head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF55300";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — idChgApplRsltCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf55300.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_6", fn: function(){ return ((dma_pageContext.get("idChgApplRsltCd") ?? "") === 'N'); } }, { id: "c_when_12", fn: function(){ return ((dma_pageContext.get("idChgApplRsltCd") ?? "") === 'R'); } }, { id: "c_otherwise_18", fn: function(){ return (!(((dma_pageContext.get("idChgApplRsltCd") ?? "") === 'N') || ((dma_pageContext.get("idChgApplRsltCd") ?? "") === 'R'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        // alert('${idChgApplRsltCd}');
        // (document.searchForm || { elements: [] }).target = "_self";
        // event.keyCode = 0;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf55300.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_confirm_onclick
 * @description btn_confirm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_confirm_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55300.btn_confirm_onclick' }); }
};

/**
 * @method
 * @name btn_logout_onclick
 * @description btn_logout 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_logout_onclick = async function(e){
    try {
        await scwin.logout()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55300.btn_logout_onclick' }); }
};

/**
 * @method
 * @name btn_confirm_2_onclick
 * @description btn_confirm_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_confirm_2_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55300.btn_confirm_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_confirm
 * @description confirm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_confirm",
        method: "post",
        action: "/register/register.do?method=updateIntegUsrIdApplView",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    await scwin.tx_fn_confirm();
};

/**
 * @method
 * @name logout
 * @description logout 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.logout = async function () {
    await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/logout.do?method=logout). 전환 대상 화면이 확정되면 연결됩니다.');
};
